// Release notes generated by the release workflow from commit messages
// (.github/workflows/release.yml, "Release notes" step):
//
//   ### New
//   - Mark a whole folder read in the backend
//   ### Fixed
//   - …
//
// They travel with each GitHub release (update notice) and are baked into
// each build (About). Anything else in the text is ignored.
import type { ChangeKind } from "./changelog";

export interface ReleaseNoteSection {
  kind: ChangeKind;
  items: string[];
}

const HEADINGS: Record<string, ChangeKind> = {
  new: "new",
  improved: "improved",
  fixed: "fixed",
};

const ORDER: readonly ChangeKind[] = ["new", "improved", "fixed"];

export function parseReleaseNotes(text: string | null | undefined): ReleaseNoteSection[] {
  if (!text) return [];
  const sections = new Map<ChangeKind, string[]>();
  let current: ChangeKind | null = null;
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    const heading = /^#{2,4}\s+(.+)$/.exec(line);
    if (heading) {
      current = HEADINGS[heading[1].trim().toLowerCase()] ?? null;
      continue;
    }
    const item = /^[-*]\s+(.+)$/.exec(line);
    if (item && current) {
      const items = sections.get(current) ?? [];
      items.push(item[1].trim());
      sections.set(current, items);
    }
  }
  return ORDER.filter((kind) => sections.has(kind)).map((kind) => ({
    kind,
    items: sections.get(kind) as string[],
  }));
}

/** Notes baked into this build by the release workflow. */
export function buildReleaseNotes(): ReleaseNoteSection[] {
  return parseReleaseNotes(__APP_RELEASE_NOTES__);
}
